  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp for administrative or cleanup purposes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  member todo_app_members @relation(fields: [todo_app_member_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([todo_app_member_id, expires_at], map: "todo_app_member_password_resets_todo_app_member_id_exp_1d94b933")
  @@index([todo_app_member_id, used_at])
  @@index([expires_at])
