  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  todo todo_app_todos @relation(fields: [todo_app_todo_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  historyEntry todo_app_todo_history_entries @relation(fields: [todo_app_todo_history_entry_id], references: [id], onDelete: Cascade, map: "todo_app_todo_history_entry_order_indexes_todo_app_tod_88787b53")

  //----
  // INDEXES
