  // spellchecker: ignore-next-line
  @@unique([todo_app_todo_history_entry_id], map: "todo_app_todo_history_entry_order_indexes_todo_app_tod_2ff488c2")
  // spellchecker: ignore-next-line
  @@index([todo_app_todo_id, position], map: "todo_app_todo_history_entry_order_indexes_todo_app_tod_e78fe8ec")
