    {
      body: {
        title: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        start_date: initialStart,
        due_date: initialDue,
      } satisfies ITodoAppTodo.ICreate,
    },
  );
  typia.assert(createdA);
  const todoIdA = createdA.id;
  const beforeA = createdA;
  // Update 1: change at least one editable field (title, description, and dates)
  const updatedStart1 = RandomGenerator.date(
    new Date(),
    1000 * 60 * 60 * 24 * 30,
  ).toISOString() satisfies string & tags.Format<"date-time">;
  const updatedDue1 = RandomGenerator.date(
    new Date(),
    1000 * 60 * 60 * 24 * 40,
  ).toISOString() satisfies string & tags.Format<"date-time">;
  const updatePayload1 = {
    title: RandomGenerator.paragraph({ sentences: 1 }),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    start_date: updatedStart1,
    due_date: updatedDue1,
  } satisfies ITodoAppTodo.IUpdate;
  const afterUpdate1 = await api.functional.todoApp.member.todos.update(
    memberAConnection,
    {
      todoId: todoIdA,
      body: updatePayload1,
    },
  );
  typia.assert(afterUpdate1);
  TestValidator.equals("todo id preserved", afterUpdate1.id, todoIdA);
  TestValidator.equals(
    "title updated",
    afterUpdate1.title,
    updatePayload1.title,
  );
  TestValidator.equals(
    "description updated",
    afterUpdate1.description,
    updatePayload1.description ?? null,
  );
  TestValidator.equals(
    "start_date updated",
    afterUpdate1.start_date,
    updatePayload1.start_date ?? null,
  );
  TestValidator.equals(
    "due_date updated",
    afterUpdate1.due_date,
    updatePayload1.due_date ?? null,
  );
  TestValidator.equals(
    "completion_status unchanged",
    afterUpdate1.completion_status,
    beforeA.completion_status,
  );
  TestValidator.equals(
    "deleted_at unchanged",
    afterUpdate1.deleted_at,
    beforeA.deleted_at,
  );
  TestValidator.equals(
    "deleted_in_trash_at unchanged",
    afterUpdate1.deleted_in_trash_at,
    beforeA.deleted_in_trash_at,
  );
  TestValidator.notEquals(
    "updated_at should change after real update",
    afterUpdate1.updated_at,
    beforeA.updated_at,
  );
  const beforeNoOpUpdatedAt = afterUpdate1.updated_at;
  // Update 2: no-op update (same editable fields)
  const afterNoOp = await api.functional.todoApp.member.todos.update(
    memberAConnection,
    {
      todoId: todoIdA,
      body: updatePayload1,
    },
  );
  typia.assert(afterNoOp);
  TestValidator.equals(
    "title preserved on no-op",
    afterNoOp.title,
    updatePayload1.title,
  );
  TestValidator.equals(
    "description preserved on no-op",
    afterNoOp.description,
    afterUpdate1.description,
  );
  TestValidator.equals(
    "start_date preserved on no-op",
    afterNoOp.start_date,
    afterUpdate1.start_date,
  );
  TestValidator.equals(
    "due_date preserved on no-op",
    afterNoOp.due_date,
    afterUpdate1.due_date,
  );
  TestValidator.equals(
    "completion_status unchanged on no-op",
    afterNoOp.completion_status,
    afterUpdate1.completion_status,
  );
  TestValidator.equals(
    "deleted_at unchanged on no-op",
    afterNoOp.deleted_at,
    afterUpdate1.deleted_at,
  );
  TestValidator.equals(
    "deleted_in_trash_at unchanged on no-op",
    afterNoOp.deleted_in_trash_at,
    afterUpdate1.deleted_in_trash_at,
  );
  TestValidator.equals(
    "updated_at unchanged on no-op",
    afterNoOp.updated_at,
    beforeNoOpUpdatedAt,
  );
  // Scenario 2: clear start_date and due_date to null
  const payload2 = {
    title: updatePayload1.title,
    description: updatePayload1.description,
    start_date: null,
    due_date: null,
  } satisfies ITodoAppTodo.IUpdate;
  const afterUpdate2 = await api.functional.todoApp.member.todos.update(
    memberAConnection,
    {
      todoId: todoIdA,
      body: payload2,
    },
  );
  typia.assert(afterUpdate2);
  TestValidator.equals("start_date cleared", afterUpdate2.start_date, null);
  TestValidator.equals("due_date cleared", afterUpdate2.due_date, null);
  TestValidator.equals("title unchanged", afterUpdate2.title, payload2.title);
  TestValidator.equals(
    "description unchanged",
    afterUpdate2.description,
    afterNoOp.description,
  );
  TestValidator.equals(
    "completion_status unchanged",
    afterUpdate2.completion_status,
    afterNoOp.completion_status,
  );
  TestValidator.equals(
    "deleted_at unchanged",
    afterUpdate2.deleted_at,
    afterNoOp.deleted_at,
  );
  TestValidator.equals(
    "deleted_in_trash_at unchanged",
    afterUpdate2.deleted_in_trash_at,
    afterNoOp.deleted_in_trash_at,
  );
  // Scenario 3: privacy boundary
  const attemptUpdateByB = async () => {
    await api.functional.todoApp.member.todos.update(memberBConnection, {
      todoId: todoIdA,
      body: {
        title: RandomGenerator.paragraph({ sentences: 1 }),
        description: RandomGenerator.paragraph({ sentences: 1 }),
        start_date: null,
        due_date: null,
      } satisfies ITodoAppTodo.IUpdate,
    });
  };
  await TestValidator.error(
    "should reject cross-member todo update",
    attemptUpdateByB,
  );
  // Ensure Member A's todo remains unchanged after rejected attempt
  // We don't have GET /todos/{id} in available SDK; so we re-apply a no-op update and verify updated_at is stable
  // by using PUT with same payload as current persisted state as proxy.
  const currentPayloadProxy = {
    title: afterUpdate2.title,
    description: afterUpdate2.description,
    start_date: afterUpdate2.start_date,
    due_date: afterUpdate2.due_date,
  } satisfies ITodoAppTodo.IUpdate;
  const afterNoOp2 = await api.functional.todoApp.member.todos.update(
    memberAConnection,
    {
      todoId: todoIdA,
      body: currentPayloadProxy,
    },
  );
  typia.assert(afterNoOp2);
  TestValidator.equals(
    "title unchanged after rejected attempt",
    afterNoOp2.title,
    afterUpdate2.title,
  );
  TestValidator.equals(
    "description unchanged after rejected attempt",
    afterNoOp2.description,
    afterUpdate2.description,
  );
  TestValidator.equals(
    "start_date unchanged after rejected attempt",
    afterNoOp2.start_date,
    afterUpdate2.start_date,
  );
  TestValidator.equals(
    "due_date unchanged after rejected attempt",
    afterNoOp2.due_date,
    afterUpdate2.due_date,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";
import { generate_random_todo_app_member_todos_create } from "../../../generate/generate_random_todo_app_member_todos_create";
import { prepare_random_todo_app_todo } from "../../../prepare/prepare_random_todo_app_todo";

export async function test_api_todo_erase_moves_owned_todo_to_trash(
  connection: api.IConnection,
): Promise<void> {
  const memberConnection: api.IConnection = { host: connection.host };
  await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppMember.IJoin,
  });
  const created: ITodoAppTodo =
    await generate_random_todo_app_member_todos_create(memberConnection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 1 }),
        description: null,
        start_date: null,
        due_date: null,
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(created);
  const indexBefore: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.member.todos.index(memberConnection, {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "asc",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(indexBefore);
  const beforeNormal = indexBefore.data.find((x) => x.id === created.id);
  TestValidator.predicate(
    "todo exists before erase",
    () => beforeNormal !== undefined,
  );
  TestValidator.equals(
    "todo is not in trash before erase",
    beforeNormal?.deleted_in_trash_at ?? null,
    null,
  );
  await api.functional.todoApp.member.todos.erase(memberConnection, {
    todoId: created.id,
  });
  const indexAfterFirst: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.member.todos.index(memberConnection, {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "asc",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(indexAfterFirst);
  const afterFirstNormal = indexAfterFirst.data.find(
    (x) => x.id === created.id && x.deleted_in_trash_at === null,
  );
  TestValidator.predicate(
    "todo removed from normal list after first erase",
    () => afterFirstNormal === undefined,
  );
  const afterFirstTrash = indexAfterFirst.data.find(
    (x) => x.id === created.id && x.deleted_in_trash_at !== null,
  );
  TestValidator.predicate(
    "todo appears in trash after first erase",
    () => afterFirstTrash !== undefined,
  );
  // Idempotency: deleting again should keep it in trash
  await api.functional.todoApp.member.todos.erase(memberConnection, {
    todoId: created.id,
  });
  const indexAfterSecond: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.member.todos.index(memberConnection, {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "asc",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTodo.IRequest,
    });
  typia.assert(indexAfterSecond);
  const afterSecondNormal = indexAfterSecond.data.find(
    (x) => x.id === created.id && x.deleted_in_trash_at === null,
  );
  TestValidator.predicate(
    "todo remains removed from normal list after second erase",
    () => afterSecondNormal === undefined,
  );
  const afterSecondTrash = indexAfterSecond.data.find(
    (x) => x.id === created.id && x.deleted_in_trash_at !== null,
  );
  TestValidator.predicate(
    "todo remains in trash after second erase",
    () => afterSecondTrash !== undefined,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { IPageITodoAppTodoHistoryEntry } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodoHistoryEntry";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import type { ITodoAppTodoHistoryEntry } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodoHistoryEntry";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";
import { generate_random_todo_app_member_todos_create } from "../../../generate/generate_random_todo_app_member_todos_create";
import { prepare_random_todo_app_todo } from "../../../prepare/prepare_random_todo_app_todo";

export async function test_api_todo_erase_idempotent_when_already_in_trash(
  connection: api.IConnection,
): Promise<void> {
  // 1) Setup: Join as a member
  const memberConnection: api.IConnection = { host: connection.host };
  const join = await authorize_member_join(memberConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies ITodoAppMember.IJoin,
  });
  // use the same connection (authorize utility already configured headers)
  typia.assert(join);
  // 2) Create todo
  const created = await generate_random_todo_app_member_todos_create(
    memberConnection,
    {
      body: {
        title: RandomGenerator.name(2),
        description: null,
        start_date: null,
        due_date: null,
      } satisfies ITodoAppTodo.ICreate,
    },
  );
  typia.assert(created);
  const todoId: string & tags.Format<"uuid"> = created.id;
  // 3) First erase -> move to trash
  await api.functional.todoApp.member.todos.erase(memberConnection, {
    todoId,
  });
  // 4) Pre-check: ensure appears in trash list and not in normal list.
  // We use completionStatusFilter=all and rely on deleted_in_trash_at field.
  const listAfterFirstErase = await api.functional.todoApp.member.todos.index(
    memberConnection,
    {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "desc",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(listAfterFirstErase);
  const idsInReturnedList = listAfterFirstErase.data.map((t) => t.id);
  TestValidator.predicate(
    "todo should be visible in the returned list after first erase",
    idsInReturnedList.includes(todoId),
  );
  TestValidator.predicate(
    "todo should be marked as in trash in returned list",
    listAfterFirstErase.data.some(
      (t) => t.id === todoId && t.deleted_in_trash_at !== null,
    ),
  );
  TestValidator.predicate(
    "todo should not appear as active (not in trash) after first erase",
    !listAfterFirstErase.data.some(
      (t) => t.id === todoId && t.deleted_in_trash_at === null,
    ),
  );
  // 5) Act: second erase (idempotent)
  await api.functional.todoApp.member.todos.erase(memberConnection, {
    todoId,
  });
  // 6) Validate idempotent behavior
  const listAfterSecondErase = await api.functional.todoApp.member.todos.index(
    memberConnection,
    {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "desc",
        page: 1,
        limit: 100,
      } satisfies ITodoAppTodo.IRequest,
    },
  );
  typia.assert(listAfterSecondErase);
  TestValidator.predicate(
    "todo should still be present in trash after second erase",
    listAfterSecondErase.data.some(
      (t) => t.id === todoId && t.deleted_in_trash_at !== null,
    ),
  );
  TestValidator.predicate(
    "todo should not reappear in normal active list after second erase",
    !listAfterSecondErase.data.some(
      (t) => t.id === todoId && t.deleted_in_trash_at === null,
    ),
  );
  // history entries still retrievable
  const historyPage =
    await api.functional.todoApp.member.todos.history_entries.index(
      memberConnection,
      {
        todoId,
        body: {
          page: 1,
          limit: 100,
        } satisfies ITodoAppTodoHistoryEntry.IRequest,
      },
    );
  typia.assert(historyPage);
  TestValidator.predicate(
    "history page should have returned entries data (may be empty but response exists)",
    historyPage.data !== undefined,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageITodoAppTodo";
import type { ITodoAppMember } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppMember";
import type { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { DeepPartial } from "@ORGANIZATION/PROJECT-api/lib/typings/DeepPartial";
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import { randint } from "tstl";
import typia, { tags } from "typia";

import { authorize_member_join } from "../../../authorize/authorize_member_join";
import { authorize_member_login } from "../../../authorize/authorize_member_login";
import { authorize_member_refresh } from "../../../authorize/authorize_member_refresh";
import { generate_random_todo_app_member_todos_create } from "../../../generate/generate_random_todo_app_member_todos_create";
import { prepare_random_todo_app_todo } from "../../../prepare/prepare_random_todo_app_todo";

export async function test_api_todo_erase_blocks_non_owned_todo_access(
  connection: api.IConnection,
): Promise<void> {
  // Create actor-specific connections
  const memberAConnection: api.IConnection = { host: connection.host };
  const memberBConnection: api.IConnection = { host: connection.host };
  // Authenticate two distinct members
  const memberAAuthorized = await authorize_member_join(memberAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies ITodoAppMember.IJoin,
  });
  typia.assert(memberAAuthorized);
  const memberBAuthorized = await authorize_member_join(memberBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
      ip: null,
    } satisfies ITodoAppMember.IJoin,
  });
  typia.assert(memberBAuthorized);
  // As member A, create a todo
  const todoA: ITodoAppTodo =
    await generate_random_todo_app_member_todos_create(memberAConnection, {
      body: {
        title: typia.random<string & tags.MinLength<1>>(),
        description: null,
        start_date: null,
        due_date: null,
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(todoA);
  // Act as member B: attempt to erase member A's todo (should fail)
  await TestValidator.httpError(
    "member B cannot erase member A's todo",
    [400, 401, 403, 404],
    async () => {
      await api.functional.todoApp.member.todos.erase(memberBConnection, {
        todoId: todoA.id,
      });
    },
  );
  // Verify from member A: todo remains visible in A list and not moved to trash
  const memberAListBefore: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.member.todos.index(memberAConnection, {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "asc",
        page: 1,
        limit: 100,
      },
    });
  typia.assert(memberAListBefore);
  const aTodoInList = memberAListBefore.data.find((t) => t.id === todoA.id);
  TestValidator.predicate(
    "member A can still see its todo",
    () => aTodoInList !== undefined,
  );
  TestValidator.equals(
    "member A's todo is not in trash",
    aTodoInList?.deleted_in_trash_at ?? null,
    null,
  );
  // Verify from member B: todo is not visible in either normal or trash
  const memberBListAfter: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.member.todos.index(memberBConnection, {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "asc",
        page: 1,
        limit: 100,
      },
    });
  typia.assert(memberBListAfter);
  const bTodoInList = memberBListAfter.data.find((t) => t.id === todoA.id);
  TestValidator.predicate(
    "member B does not see member A's todo",
    () => bTodoInList === undefined,
  );
  // Re-try the forbidden erase attempt again as member B
  await TestValidator.httpError(
    "member B cannot erase member A's todo (retry)",
    [400, 401, 403, 404],
    async () => {
      await api.functional.todoApp.member.todos.erase(memberBConnection, {
        todoId: todoA.id,
      });
    },
  );
  // Validate again: member A unchanged
  const memberAListAfterRetry: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.member.todos.index(memberAConnection, {
      body: {
        completionStatusFilter: "all",
        sortBy: "created_at",
        sortDirection: "asc",
        page: 1,
        limit: 100,
      },
    });
  typia.assert(memberAListAfterRetry);
  const aTodoAfterRetry = memberAListAfterRetry.data.find(
    (t) => t.id === todoA.id,
  );
  TestValidator.predicate(
    "member A still sees its todo after retry",
    () => aTodoAfterRetry !== undefined,
  );
  TestValidator.equals(
    "member A's todo still not in trash after retry",
    aTodoAfterRetry?.deleted_in_trash_at ?? null,
    null,
  );
  // Validate again: member B unchanged
  const memberBListAfterRetry: IPageITodoAppTodo.ISummary =
    await api.functional.todoApp.member.todos.index(memberBConnection, {
