  await api.functional.todoApp.member.todos.update(memberALoginConnection, {
    todoId: todo2.id,
    body: {
      title: `${todo2.title} ${RandomGenerator.alphabets(4)}`,
      description: null,
      start_date: new Date(Date.now() + 1000 * 120).toISOString(),
      due_date: null,
