import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postTodoAppAuthMemberLogin(props: {
  ip: string;
  body: ITodoAppMember.ILogin;
}): Promise<ITodoAppMember.IAuthorized> {
  const member = await MyGlobal.prisma.todo_app_members.findFirst({
    where: { email: props.body.email },
    select: {
      id: true,
      email: true,
      status: true,
      password_hash: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      userProfile: {
        select: {
          display_name: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
        },
      },
    },
  });
  if (member === null) {
    throw new HttpException("Invalid credentials", 401);
  }
  if (member.deleted_at !== null) {
    throw new HttpException("Invalid credentials", 401);
  }
  if (member.status !== "active") {
    throw new HttpException("Invalid credentials", 401);
  }
  const verified = await PasswordUtil.verify(
    props.body.password,
    member.password_hash,
  );
  if (!verified) {
    throw new HttpException("Invalid credentials", 401);
  }
  const nowIso = toISOStringSafe(new Date());
  const accessExpiredIso = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshableUntilIso = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const sessionId = typia.assert<string & tags.Format<"uuid">>(v4());
  const session = await MyGlobal.prisma.todo_app_member_sessions.create({
    data: {
      id: sessionId,
      todo_app_member_id: member.id,
      ip: props.ip,
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: typia.assert<string & tags.Format<"date-time">>(nowIso),
      expired_at: typia.assert<string & tags.Format<"date-time">>(
        accessExpiredIso,
      ),
    },
  });
  const access = jwt.sign(
    {
      type: "member",
      id: member.id,
      session_id: session.id,
      created_at: typia.assert<string & tags.Format<"date-time">>(nowIso),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );
  const refresh = jwt.sign(
    {
      type: "member",
      id: member.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: typia.assert<string & tags.Format<"date-time">>(nowIso),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );
  return {
    id: member.id,
    email: member.email,
    status: member.status,
    created_at: typia.assert<string & tags.Format<"date-time">>(
      toISOStringSafe(member.created_at),
    ),
    updated_at: typia.assert<string & tags.Format<"date-time">>(
      toISOStringSafe(member.updated_at),
    ),
    deleted_at:
      member.deleted_at === null
        ? null
        : typia.assert<string & tags.Format<"date-time">>(
            toISOStringSafe(member.deleted_at),
          ),
    profile: {
      display_name: member.userProfile ? member.userProfile.display_name : null,
      created_at: member.userProfile
        ? typia.assert<string & tags.Format<"date-time">>(
            toISOStringSafe(member.userProfile.created_at),
          )
        : null,
      updated_at: member.userProfile
        ? typia.assert<string & tags.Format<"date-time">>(
            toISOStringSafe(member.userProfile.updated_at),
          )
        : null,
      deleted_at:
        member.userProfile && member.userProfile.deleted_at !== null
          ? typia.assert<string & tags.Format<"date-time">>(
              toISOStringSafe(member.userProfile.deleted_at),
            )
          : null,
    },
    token: {
      access,
      refresh,
      expired_at: typia.assert<string & tags.Format<"date-time">>(
        accessExpiredIso,
      ),
      refreshable_until: typia.assert<string & tags.Format<"date-time">>(
        refreshableUntilIso,
      ),
    },
  };
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { ITodoAppTodo } from "@ORGANIZATION/PROJECT-api/lib/structures/ITodoAppTodo";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function putTodoAppMemberTodosTodoIdRestore(props: {
  member: MemberPayload;
  todoId: string & tags.Format<"uuid">;
}): Promise<ITodoAppTodo> {
  const todo = await MyGlobal.prisma.todo_app_todos.findFirstOrThrow({
    where: {
      id: props.todoId,
      todo_app_member_id: props.member.id,
    },
    select: {
      id: true,
      title: true,
      description: true,
      start_date: true,
      due_date: true,
      completion_status: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      deleted_in_trash_at: true,
    } satisfies Prisma.todo_app_todosSelect,
  });
  if (todo.deleted_in_trash_at === null) {
    throw new HttpException(
      "Todo restore is invalid in current lifecycle state",
      400,
    );
  }
  await MyGlobal.prisma.$transaction(async (tx) => {
    await tx.todo_app_todos.update({
      where: {
        id: props.todoId,
        todo_app_member_id: props.member.id,
      },
      data: {
        deleted_in_trash_at: null,
      },
    });
  });
  const restored = await MyGlobal.prisma.todo_app_todos.findFirstOrThrow({
    where: {
      id: props.todoId,
      todo_app_member_id: props.member.id,
    },
    select: {
      id: true,
      title: true,
      description: true,
      start_date: true,
      due_date: true,
      completion_status: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      deleted_in_trash_at: true,
    } satisfies Prisma.todo_app_todosSelect,
  });
  return {
    id: restored.id,
    title: restored.title,
    description: restored.description ?? null,
    start_date:
      restored.start_date === null
        ? null
        : toISOStringSafe(restored.start_date),
    due_date:
      restored.due_date === null ? null : toISOStringSafe(restored.due_date),
    completion_status: restored.completion_status,
    created_at: toISOStringSafe(restored.created_at),
    updated_at: toISOStringSafe(restored.updated_at),
    deleted_at:
      restored.deleted_at === null
        ? null
        : toISOStringSafe(restored.deleted_at),
    deleted_in_trash_at:
      restored.deleted_in_trash_at === null
        ? null
        : toISOStringSafe(restored.deleted_in_trash_at),
  } satisfies ITodoAppTodo;
}

